import{_ as r,l,o as a,c as i,v as s,p as n,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"safetensors","description":"","frontmatter":{"title":"safetensors","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/safetensors-format.md","filePath":"llm/safetensors-format.md","lastUpdated":1789023840000}'),m={name:"llm/safetensors-format.md"};function f(h,e,_,u,E,P){const t=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=s('<h1 id="safetensors" tabindex="-1">safetensors <a class="header-anchor" href="#safetensors" aria-label="Permalink to &quot;safetensors&quot;">​</a></h1><div class="epigraph"><p>张量文件应当是可以 mmap 的字节布局加一份 JSON 头，而不是一棵会执行代码的 pickle 树。</p><footer>—— Hugging Face safetensors 规范与安全公告；对照 Python pickle 的任意代码执行面</footer></div><p><a href="/llm/weight-loading-streaming">上一课</a>把加载当成带宽与驻留。格式决定 <em>能不能安全地 mmap、能不能零拷贝、头部是否可读</em>。PyTorch <code>.pt</code> 默认 pickle，恶意文件可在 <code>load</code> 时执行代码。safetensors 用固定头 + 偏移表 + 原始张量字节，加载路径无执行。本课写格式契约与对启动的影响；它不是量化算法，也可以装 FP16 或量化后的块。GGUF 是另一生态的容器，见 <a href="/llm/gguf">GGUF</a>。本单元「引擎里的细节」到 safetensors 收束，下一单元离开 CUDA 服务栈。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>检查点分发是供应链：来自 Hub 的文件被服务进程以高权限打开。pickle 的攻击面不可接受。另一些格式（原始 bin）缺形状与 dtype 元数据，加载慢且易错。缺口是：一份按偏移 mmap 的张量字典，dtype/shape 在头里，校验和可选。加载器按名切片映射到设备，不必把整个文件读进主机 RAM 再 <code>cudaMemcpy</code>——大模型上主机体峰值本身会 OOM。</p><p>多框架：同一文件应对 PyTorch、NumPy、JAX 可读。这要求头是 JSON、体是小端原始数组，而不是 Python 对象图。</p><p><span class="marginnote">safetensors 不管量化语义。文件里可以是 <code>int8</code> 加 scale 张量，语义由模型代码解释。不要说「转成 safetensors 就 4-bit 了」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>文件：8 字节头长、JSON 头（张量名 → dtype, shape, 偏移）、然后数据区对齐。加载：mmap，按张量创建指向文件的视图，再异步拷到 GPU 或直接给 CPU 核。与流式加载配合：按层名顺序拷贝。校验：可选哈希在发布侧做，热路径可跳过或抽检。</p><p>和 GGUF 比：safetensors 不内置分词器与架构超参；那些仍在 <code>config.json</code>。服务启动要读两份。GGUF 把元数据打进同一文件，本地单文件分发更省事。GPU 训练/推理生态以 safetensors + config 为默认。</p>',10)),(a(),n(c,null,{default:o(()=>[p(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PKL%5B%22pickle%20.pt%22%5D%20--%3E%20RCE%5B%22load%20%E6%97%B6%E5%8F%AF%E6%89%A7%E8%A1%8C%E4%BB%A3%E7%A0%81%22%5D%0A%20%20ST%5B%22safetensors%22%5D%20--%3E%20MM%5B%22mmap%20%E5%81%8F%E7%A7%BB%E8%A1%A8%22%5D%0A%20%20MM%20--%3E%20DEV%5B%22%E6%8C%89%E5%BC%A0%E9%87%8F%E6%8B%B7%E5%88%B0%E8%AE%BE%E5%A4%87%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无执行 + mmap 使加载器成为纯字节搬运，便于与<a href="/llm/weight-loading-streaming">自定义加载流水</a>重叠。JSON 头解析是一次性 CPU 微秒～毫秒，相对百 GB 搬运可忽略。对齐保证直接转 <code>bfloat16</code> 视图合法。跨进程共享只读 mmap 可减冷启动主机内存（fork 前打开），GPU 仍要各自一份设备副本。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用 <code>pickle.loads</code> 加载来路不明的检查点。不要把 safetensors 当万能容器塞 Python 对象。与 GGUF 的选择按运行时：vLLM/HF 一条，llama.cpp 一条。下一课程单元改谈 GPU 之外的运行时，从 ONNX Runtime 开始。</p><p>出处：Hugging Face safetensors 规范与安全文档。无单独会议论文，不编造 arXiv。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>safetensors 是可 mmap 的无执行张量容器；替代 pickle 检查点。</li><li>头 JSON、体原始数组；量化语义在模型代码。</li><li>与 config.json 配对；GGUF 是单文件本地生态。</li><li>零拷贝视图减主机峰值，设备仍要驻留副本。</li><li>加载与按层流式兼容。</li><li>下一课：ONNX Runtime。</li><li>出处：Hugging Face safetensors。</li></ul>',7))])}const B=r(m,[["render",f]]);export{A as __pageData,B as default};
